namespace CafeSystem.Models;
public sealed class Role { public int Id { get; set; } public string Name { get; set; } = ""; public string? Description { get; set; } public List<CafeUser> Users { get; set; } = []; }
public sealed class CafeUser { public int Id { get; set; } public Guid? AuthUserId { get; set; } public int RoleId { get; set; } public Role Role { get; set; } = null!; public string? Phone { get; set; } public string? Email { get; set; } public string? PasswordHash { get; set; } public string FullName { get; set; } = ""; public DateTime CreatedAt { get; set; } }
public sealed class StaffProfile { public int Id { get; set; } public int UserId { get; set; } public string? Bio { get; set; } public string? PortfolioUrl { get; set; } public string? AvatarUrl { get; set; } public string[] Specialties { get; set; } = []; }
public sealed class Service { public int Id { get; set; } public string Name { get; set; } = ""; public decimal Price { get; set; } }
public sealed class Booking { public int Id { get; set; } public int CustomerId { get; set; } public int StaffId { get; set; } public int ServiceId { get; set; } public DateTime BookingDate { get; set; } public string TimeSlot { get; set; } = ""; public string Status { get; set; } = "Pending"; public decimal TotalPrice { get; set; } public string? CustomerNote { get; set; } public DateTime CreatedAt { get; set; } }
public sealed class TableCafe { public int Id { get; set; } public string TableNumber { get; set; } = ""; public string? CurrentSession { get; set; } public DateTime? BillRequestedAt { get; set; } public DateTime? OpenedAt { get; set; } }
public sealed class MenuCategory { public int Id { get; set; } public string Name { get; set; } = ""; }
public sealed class MenuItem { public int Id { get; set; } public int CategoryId { get; set; } public string Name { get; set; } = ""; public decimal Price { get; set; } public bool IsAvailable { get; set; } = true; }
public sealed class CafeOrder { public int Id { get; set; } public int TableId { get; set; } public string Status { get; set; } = "Dining"; public decimal TotalAmount { get; set; } public DateTime CreatedAt { get; set; } }
public sealed class OrderItem { public int Id { get; set; } public int OrderId { get; set; } public int MenuItemId { get; set; } public int Quantity { get; set; } = 1; public string KdsStatus { get; set; } = "Pending"; public string? Note { get; set; } }
public sealed class Payment { public int Id { get; set; } public int ReferenceId { get; set; } public string ReferenceType { get; set; } = ""; public decimal Amount { get; set; } public string Status { get; set; } = "Success"; public string Method { get; set; } = "UNKNOWN"; public DateTime PaidAt { get; set; } }
